            MarqueeText(
                text = state.name ?: stringResource(R.string.unsaved_preset_description),
                maxWidth = sizes.activePresetLength,
                modifier = Modifier.weight(1f, false),
                style = style)
            AnimatedVisibility(state.isModified) {
                Text(" *", style = style)
            }
        }
    }
}

