								style = MaterialTheme.typography.bodySmall,
								modifier = Modifier.padding(start = 16.dp)
							)
						}
					}
				}

				// Age Section
				Column {
					Text(
						text = stringResource(id = R.string.profile_age_label),
						style = MaterialTheme.typography.headlineMedium,
