                    ),
                    //悬浮高度，可细分为默认，按压下的，禁用时的等
                    elevation = ButtonDefaults.buttonElevation(defaultElevation = 5.dp),
                    border = BorderStroke(2.dp, Color.Red),//加边框，可用纯色，也可以用brush多色
                ) {
                    Text(text = "槐花黄绿")
                }
                //其他按钮的elevation、border等属性也是触类旁通，不再逐一演示
                TextButton(
