                },
                    label = { Text(text = "AssistChip") },
                    leadingIcon = {
                        Icon(
                            imageVector = Icons.Default.FavoriteBorder,
                            contentDescription = null,
                            modifier = Modifier.clickable {
                                /*这里可以单独处理chip内部的icon的点击事件*/
                                Toast.makeText(
                                    context,
                                    "FavoriteBorder图标被点击",
