                                ).show()
                            }
                        )
                    },
                    trailingIcon = {
                        Icon(
                            imageVector = Icons.Default.Hub,
                            contentDescription = null
                        )
                    }
                )
                ElevatedAssistChip(onClick = { }, label = { Text(text = "ElevatedAssistChip") })

            }
            Row(
