@Composable
private fun Render(
    state: State<UIState>,
    onInputTextChanged: (String) -> Unit,
    onSearchGroupSelected: (SearchGroup) -> Unit,
    onSearchPressed: () -> Unit,
    onSeriesTrack: (ResultModel) -> Unit,
    onSnackbarShown: () -> Unit
) {
    val snackbarHostState = remember { SnackbarHostState() }

    Scaffold(
        snackbarHost = {
            SnackbarHost(
                hostState = snackbarHostState,
                modifier = Modifier.semantics { testTag = SearchTags.Snackbar }
            )
        },
        modifier = Modifier.semantics { testTag = SearchTags.Root }
    ) { paddingValues ->
        Column(
            modifier = Modifier
                .fillMaxSize()
                .padding(paddingValues),
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            InputText(
                state.value.searchText,
                state.value.isSearchTextError,
                onInputTextChanged,
                onSearchPressed
            )
            SearchGroup(state.value.searchGroup, onSearchGroupSelected)
            if (state.value.isSearching) {
                CircularProgressIndicator()
            } else {
                SearchButton(state.value.isSearching, onSearchPressed)
            }
            Divider(modifier = Modifier.padding(8.dp))
            SearchResults(state.value.resultModels, onSeriesTrack)
        }
    }

    val snackbar = state.value.errorSnackbar
    if (snackbar != null) {
        val message = stringResource(id = snackbar.stringRes, snackbar.formatText)
        LaunchedEffect(message) {
            snackbarHostState.showSnackbar(message = message, duration = SnackbarDuration.Short)
            onSnackbarShown()
        }
    }
}

